head.script:
//
window.PXL_WORKER_BASE_URL = 'https://<MY_WORKER_URL>';   // e.g. 'https://px-api.your-name.workers.dev'
(function () {
  var theme = 'light';
  try { theme = localStorage.getItem('pxl-theme') === 'dark' ? 'dark' : 'light'; } catch (e) {}
  document.documentElement.setAttribute('data-theme', theme);
})();
//

head.b:skin:
/* ==========================================================================
   1. Design tokens (light = default, dark = [data-theme="dark"])
   ========================================================================== */
:root {
  --brand: #32cd32;
  --brand-strong: #22a822;
  --brand-ink: #04120a;
  --brand-soft: rgba(50, 205, 50, 0.12);
  --brand-glow: 0 0 0 rgba(50, 205, 50, 0);

  --bg: #f8f9fa;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --surface-glass: rgba(255, 255, 255, 0.85);
  --border: #e3e6eb;
  --text: #15181d;
  --text-muted: #5f6772;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 6px 18px rgba(16, 24, 40, 0.06);
  --shadow-hover: 0 4px 10px rgba(16, 24, 40, 0.08), 0 16px 32px rgba(16, 24, 40, 0.10);
  --live: #e11d48;
  --live-soft: rgba(225, 29, 72, 0.10);
  --card-shadow: 0 4px 12px rgba(0, 0, 0, 0.05);
  --card-head: #f4f5f7;

  --radius: 14px;
  --radius-sm: 9px;
  --container: 1240px;
  --header-h: 64px;
  --font: 'Cairo', Tahoma, 'Segoe UI', Arial, sans-serif;
}

[data-theme="dark"] {
  --brand: #3ee63e;
  --brand-strong: #32cd32;
  --brand-soft: rgba(62, 230, 62, 0.14);
  --brand-glow: 0 0 22px rgba(62, 230, 62, 0.35);

  --bg: #07090c;
  --surface: #10141a;
  --surface-2: #161b23;
  --surface-glass: rgba(14, 18, 24, 0.72);
  --border: rgba(255, 255, 255, 0.08);
  --text: #f2f5f8;
  --text-muted: #9aa4b1;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.5), 0 10px 26px rgba(0, 0, 0, 0.35);
  --shadow-hover: 0 0 0 1px rgba(62, 230, 62, 0.35), 0 18px 40px rgba(0, 0, 0, 0.55);
  --live: #ff3b5c;
  --live-soft: rgba(255, 59, 92, 0.14);
  --card-shadow: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 22px rgba(0, 0, 0, 0.35);
  --card-head: rgba(255, 255, 255, 0.03);
  color-scheme: dark;
}

/* ==========================================================================
   2. Base
   ========================================================================== */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.7;
  transition: background-color .25s ease, color .25s ease;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
a:hover { color: var(--brand-strong); }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; border-radius: 6px; }
.container { width: 100%; max-width: var(--container); margin-inline: auto; padding-inline: 16px; }
.visually-hidden { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.section, .widget, .widget-content { margin: 0; }

.section-title {
  display: flex; align-items: center; gap: 10px;
  margin: 0 0 16px; font-size: 1.25rem; font-weight: 800;
}
.section-title::before {
  content: ''; width: 6px; height: 22px; border-radius: 4px; background: var(--brand); box-shadow: var(--brand-glow);
}

/* ==========================================================================
   3. Header (sticky, glass) - RTL: logo right, nav center, toggle left
   ========================================================================== */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: var(--surface-glass);
  -webkit-backdrop-filter: saturate(160%) blur(14px);
  backdrop-filter: saturate(160%) blur(14px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  height: var(--header-h);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
}
.logo {
  justify-self: start;
  display: inline-flex; align-items: center; gap: 10px;
  font-weight: 800; font-size: 1.35rem; letter-spacing: .3px;
  direction: ltr; white-space: nowrap;
}
.logo__mark {
  width: 36px; height: 36px; display: grid; place-items: center;
  border-radius: 10px; background: var(--brand); color: var(--brand-ink);
  font-size: .95rem; box-shadow: var(--brand-glow);
}
.logo__text b { color: var(--brand-strong); }
[data-theme="dark"] .logo__text b { color: var(--brand); }

.main-nav ul { list-style: none; margin: 0; padding: 0; display: flex; gap: 4px; }
.main-nav a {
  display: block; padding: 8px 14px; border-radius: 999px;
  font-weight: 700; font-size: .95rem; color: var(--text-muted);
  transition: color .2s, background-color .2s;
}
.main-nav a:hover, .main-nav a.is-active { color: var(--text); background: var(--brand-soft); }

.header-actions { justify-self: end; display: flex; align-items: center; gap: 6px; }
.icon-btn {
  width: 42px; height: 42px; display: grid; place-items: center;
  border-radius: 12px; border: 1px solid var(--border);
  background: var(--surface); color: var(--text);
  transition: border-color .2s, box-shadow .2s, transform .1s;
}
.icon-btn:hover { border-color: var(--brand); box-shadow: var(--brand-glow); }
.icon-btn:active { transform: scale(.96); }
.icon-btn svg { width: 20px; height: 20px; }
.icon-sun { display: none; }
[data-theme="dark"] .icon-sun { display: block; }
[data-theme="dark"] .icon-moon { display: none; }
.menu-toggle { display: none; }

@media (max-width: 860px) {
  .header-inner { grid-template-columns: 1fr auto; }
  .menu-toggle { display: grid; }
  .main-nav {
    position: fixed; inset: var(--header-h) 0 auto 0;
    background: var(--surface); border-bottom: 1px solid var(--border); box-shadow: var(--shadow);
    padding: 10px 16px 16px;
    transform: translateY(-8px); opacity: 0; visibility: hidden;
    transition: opacity .2s, transform .2s, visibility .2s;
  }
  .main-nav.is-open { opacity: 1; transform: none; visibility: visible; }
  .main-nav ul { flex-direction: column; gap: 2px; }
  .main-nav a { padding: 12px 14px; border-radius: var(--radius-sm); font-size: 1rem; }
}

/* ==========================================================================
   4. HOME: Today's matches (rendered by fetchMatches(), grouped by league)
   ========================================================================== */
.fixtures { padding-block: 24px 8px; }
.fixtures-head {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px;
  margin-bottom: 18px;
}
.fixtures-head .section-title { margin: 0; font-size: 1.45rem; }
/* Thick lime accent bar on the right (inline-start in RTL) */
.fixtures-head .section-title::before { width: 7px; height: 30px; }
.fixtures-date { color: var(--text-muted); font-weight: 700; font-size: .92rem; }

/* League groups */
.league-group { margin-bottom: 26px; }
.league-group:last-child { margin-bottom: 0; }
.league-group__title {
  display: flex; align-items: center; gap: 10px;
  margin: 0 0 12px; font-size: 1.02rem; font-weight: 800;
}
.league-group__logo { width: 24px; height: 24px; object-fit: contain; }
.league-group__count {
  margin-inline-start: auto;
  padding: 2px 10px; border-radius: 999px;
  background: var(--surface); border: 1px solid var(--border);
  font-size: .75rem; font-weight: 700; color: var(--text-muted);
}
.match-list { display: grid; grid-template-columns: 1fr; gap: 14px; }
@media (min-width: 760px) { .match-list { grid-template-columns: repeat(2, minmax(0, 1fr)); } }

/* Match card */
.match-card {
  display: block;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--card-shadow);
  overflow: hidden;
  color: inherit;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
a.match-card:hover { transform: translateY(-3px); border-color: var(--brand); box-shadow: var(--shadow-hover); color: inherit; }

.match-card__top {                       /* league right, round left (RTL) */
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 9px 16px;
  background: var(--card-head);
  border-bottom: 1px solid var(--border);
  font-size: .8rem; font-weight: 700; color: var(--text-muted);
}
.match-card__league { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.match-card__round { flex-shrink: 0; }

.match-card__body {                      /* Team 1 right | center | Team 2 left (RTL) */
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 18px 16px;
}
.team {
  flex: 1 1 0; min-width: 0;
  display: flex; flex-direction: column; align-items: center; gap: 8px; text-align: center;
}
.team__logo {
  position: relative;
  width: 58px; height: 58px; border-radius: 50%;
  display: grid; place-items: center;
  background: var(--surface-2); border: 1px solid var(--border);
  overflow: hidden;
}
.team__initials { font-weight: 800; font-size: .9rem; color: var(--text-muted); }
.team__logo img {
  position: absolute; inset: 0; margin: auto;
  width: 42px; height: 42px; object-fit: contain;
  background: var(--surface-2);
}
.team__name { font-weight: 800; font-size: .95rem; line-height: 1.4; max-width: 100%; overflow-wrap: anywhere; }

.match-center { flex: 0 0 auto; display: flex; flex-direction: column; align-items: center; gap: 7px; min-width: 96px; }
.match-time {
  direction: ltr; font-size: 1.35rem; font-weight: 800; letter-spacing: .5px;
  padding: 3px 14px; border-radius: 10px; background: var(--surface-2);
}
.match-score {
  /* Flex follows the page direction: first number = Team 1, on Team 1's side */
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 1.5rem; font-weight: 800;
  padding: 2px 14px; border-radius: 10px; background: var(--surface-2);
}
.match-score .sep { color: var(--text-muted); font-weight: 600; }

.badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 2px 10px; border-radius: 999px;
  font-size: .74rem; font-weight: 800; white-space: nowrap;
  background: var(--surface-2); color: var(--text-muted);
}
.badge--live { background: var(--live-soft); color: var(--live); }
.badge--live::before {
  content: ''; width: 7px; height: 7px; border-radius: 50%; background: var(--live);
  animation: pxl-pulse 1.6s infinite;
}

/* Live card: subtle red highlight */
.match-card--live { border-color: rgba(225, 29, 72, .35); box-shadow: 0 0 0 1px rgba(225, 29, 72, .10), var(--card-shadow); }
.match-card--live .match-score { color: var(--live); }
.match-card--finished .match-score { color: var(--text-muted); }

.match-card__bottom {                    /* commentator right, channel left (RTL) */
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 9px 16px;
  border-top: 1px solid var(--border);
  font-size: .8rem; color: var(--text-muted);
}
.match-card__meta { display: inline-flex; align-items: center; gap: 6px; min-width: 0; }
.match-card__meta span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.match-card__meta svg { width: 15px; height: 15px; flex-shrink: 0; color: var(--brand-strong); }
[data-theme="dark"] .match-card__meta svg { color: var(--brand); }

/* Loading / error / empty */
.px-loader {
  display: grid; justify-items: center; gap: 14px;
  padding: 48px 16px; color: var(--text-muted); font-weight: 700;
}
.px-spinner {
  width: 44px; height: 44px; border-radius: 50%;
  border: 4px solid var(--surface-2); border-top-color: var(--brand);
  animation: px-spin .8s linear infinite;
}
@keyframes px-spin { to { transform: rotate(360deg); } }
.match-message {
  display: grid; justify-items: center; gap: 12px;
  padding: 32px 16px; text-align: center; color: var(--text-muted);
  background: var(--surface); border: 1px dashed var(--border); border-radius: var(--radius);
}
.px-retry {
  padding: 8px 20px; border-radius: 999px;
  background: var(--brand); color: var(--brand-ink); font-weight: 800;
  box-shadow: var(--brand-glow);
}
.px-retry:hover { background: var(--brand-strong); }

@keyframes pxl-pulse {
  0% { box-shadow: 0 0 0 0 rgba(225, 29, 72, .6); }
  70% { box-shadow: 0 0 0 8px rgba(225, 29, 72, 0); }
  100% { box-shadow: 0 0 0 0 rgba(225, 29, 72, 0); }
}

/* ==========================================================================
   5. MATCH POST: streaming arena (16:9 player + ads)
   ========================================================================== */
.arena { padding-block: 20px 4px; }
.arena-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; margin-bottom: 12px; }
.arena-title { margin: 0; font-size: 1.35rem; line-height: 1.45; font-weight: 800; }
.live-pill {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 4px 12px; border-radius: 999px;
  background: var(--live-soft); color: var(--live); font-weight: 800; font-size: .85rem;
}
.live-pill::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--live); animation: pxl-pulse 1.6s infinite; }

.arena-grid { display: grid; grid-template-columns: 1fr; gap: 16px; align-items: start; }
.arena-center { min-width: 0; display: grid; gap: 14px; }
@media (min-width: 1200px) {
  .arena-grid { grid-template-columns: 160px minmax(0, 1fr) 160px; }
}

.player-frame {
  position: relative; width: 100%; aspect-ratio: 16 / 9;
  border-radius: var(--radius); overflow: hidden; background: #000;
  box-shadow: var(--shadow); border: 1px solid var(--border);
}
[data-theme="dark"] .player-frame { box-shadow: 0 0 0 1px rgba(62, 230, 62, .25), 0 0 40px rgba(62, 230, 62, .12); }
@supports not (aspect-ratio: 16 / 9) { .player-frame { height: 0; padding-top: 56.25%; } }
.player-frame iframe, .player-frame video, .player-placeholder {
  position: absolute; inset: 0; width: 100%; height: 100%; border: 0;
}
.player-placeholder {
  display: grid; place-items: center; align-content: center; gap: 10px; text-align: center;
  color: #cfd6dd; font-weight: 700;
  background: radial-gradient(ellipse at center, #10161d 0%, #000 75%);
}
.player-placeholder svg { width: 54px; height: 54px; color: var(--brand); filter: drop-shadow(0 0 12px rgba(50, 205, 50, .5)); }

/* Ad slots (post view only) */
.ad-slot {
  display: grid; place-items: center; width: 100%;
  border-radius: var(--radius-sm);
  background: repeating-linear-gradient(45deg, var(--surface-2), var(--surface-2) 10px, var(--surface) 10px, var(--surface) 20px);
  border: 1px dashed var(--border);
  color: var(--text-muted); font-size: .8rem; overflow: hidden;
}
.ad-slot .widget, .ad-slot .widget-content { width: 100%; display: grid; place-items: center; }
.ad-slot--h { min-height: 100px; }   /* 320x100 mobile, 728x90 desktop */
.ad-slot--v { min-height: 600px; }   /* 160x600 skyscraper */
.ad-side { display: none; }
.ad-label { padding: 8px; }
@media (min-width: 768px) { .ad-slot--h { min-height: 90px; } }
@media (min-width: 1200px) { .ad-side { display: grid; position: sticky; top: calc(var(--header-h) + 16px); } }

/* ==========================================================================
   6. Content + sidebar
   ========================================================================== */
.content-wrap { display: grid; grid-template-columns: 1fr; gap: 24px; padding-block: 24px 40px; }
@media (min-width: 1024px) { .content-wrap { grid-template-columns: minmax(0, 1fr) 320px; } }

/* Post cards (home "latest", label & search pages) */
.post-grid { display: grid; grid-template-columns: 1fr; gap: 18px; }
@media (min-width: 600px) { .post-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1280px) { .post-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.card {
  display: flex; flex-direction: column;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  overflow: hidden; box-shadow: var(--shadow);
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); border-color: var(--brand); }
.card__media { position: relative; display: block; aspect-ratio: 16 / 9; overflow: hidden; background: var(--surface-2); }
.card__media img { width: 100%; height: 100%; object-fit: cover; transition: transform .45s ease; }
.card:hover .card__media img { transform: scale(1.05); }
.card__placeholder { position: absolute; inset: 0; display: grid; place-items: center; font-size: 2rem; font-weight: 800; color: var(--brand); direction: ltr; }
.card__body { display: flex; flex-direction: column; gap: 8px; padding: 14px 16px 16px; flex: 1; }
.card__tag {
  align-self: flex-start; padding: 2px 10px; border-radius: 999px;
  background: var(--brand-soft); color: var(--brand-strong); font-size: .78rem; font-weight: 800;
}
[data-theme="dark"] .card__tag { color: var(--brand); }
.card__title { margin: 0; font-size: 1.05rem; line-height: 1.5; font-weight: 800; }
.card__excerpt {
  margin: 0; color: var(--text-muted); font-size: .92rem;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.card__date { margin-top: auto; color: var(--text-muted); font-size: .8rem; }
.empty-state { padding: 40px 16px; text-align: center; color: var(--text-muted); background: var(--surface); border: 1px dashed var(--border); border-radius: var(--radius); }
.pager { display: flex; justify-content: space-between; gap: 12px; margin-top: 24px; }
.pager a {
  display: inline-flex; align-items: center; gap: 8px; padding: 10px 18px; border-radius: 999px;
  background: var(--surface); border: 1px solid var(--border); font-weight: 700; box-shadow: var(--shadow);
}
.pager a:hover { border-color: var(--brand); color: var(--text); box-shadow: var(--brand-glow); }

/* Post / page article */
.post-full { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 22px; box-shadow: var(--shadow); }
.post-full__title { margin: 0 0 6px; font-size: 1.5rem; line-height: 1.45; font-weight: 800; }
.post-meta { color: var(--text-muted); font-size: .88rem; margin-bottom: 18px; }
.post-body { font-size: 1.02rem; overflow-wrap: anywhere; }
.post-body img { border-radius: var(--radius-sm); margin-inline: auto; }
.post-body a { color: var(--brand-strong); text-decoration: underline; text-underline-offset: 3px; }
[data-theme="dark"] .post-body a { color: var(--brand); }
.post-body iframe { max-width: 100%; }
.post-body [data-stream-src] { display: none; }
/* Standard article typography */
.post-full__title[hidden] { display: none; }
.post-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.post-meta__sep { opacity: .6; }
.post-body { line-height: 1.95; }
.post-body > :first-child { margin-top: 0; }
.post-body p { margin: 0 0 1.1em; }
.post-body h2, .post-body h3, .post-body h4 { margin: 1.6em 0 .6em; line-height: 1.5; font-weight: 800; }
.post-body h2 { font-size: 1.3rem; padding-inline-start: 12px; border-inline-start: 4px solid var(--brand); }
.post-body h3 { font-size: 1.12rem; }
.post-body h4 { font-size: 1rem; }
.post-body ul, .post-body ol { margin: 0 0 1.1em; padding-inline-start: 1.4em; }
.post-body li { margin-bottom: .35em; }
.post-body li::marker { color: var(--brand-strong); }
.post-body blockquote {
  margin: 1.4em 0; padding: 14px 18px; border-radius: var(--radius-sm);
  background: var(--surface-2); border-inline-start: 4px solid var(--brand); color: var(--text);
}
.post-body table { width: 100%; border-collapse: collapse; margin: 1.2em 0; font-size: .95rem; display: block; overflow-x: auto; }
.post-body th, .post-body td { padding: 10px 12px; border: 1px solid var(--border); text-align: start; }
.post-body th { background: var(--surface-2); font-weight: 800; }
.post-body .tr-caption-container { display: table; margin: 1.2em auto; }
.post-body .tr-caption { font-size: .85rem; color: var(--text-muted); padding-top: 6px; }
.post-body hr { border: 0; height: 1px; background: var(--border); margin: 2em 0; }
.post-body code { padding: 2px 6px; border-radius: 6px; background: var(--surface-2); font-size: .9em; direction: ltr; unicode-bidi: isolate; }
.post-body iframe, .post-body video { display: block; width: 100%; aspect-ratio: 16 / 9; height: auto; border: 0; border-radius: var(--radius-sm); margin: 1.2em 0; }
.empty-state--404 { display: grid; justify-items: center; gap: 10px; padding: 56px 16px; }
.empty-state--404 strong { font-size: 3rem; line-height: 1; color: var(--brand-strong); }
.empty-state--404 p { margin: 0; }
.empty-state--404 .px-retry { text-decoration: none; }

/* ============================ Match details page ============================ */
.match-page { display: grid; gap: 16px; }
.match-hero {
  position: relative; overflow: hidden;
  border-radius: var(--radius); border: 1px solid #1f2937;
  background:
    radial-gradient(120% 90% at 50% -10%, rgba(50, 205, 50, .18), transparent 60%),
    linear-gradient(165deg, #0b1220 0%, #0f172a 55%, #0b1a10 100%);
  color: #f1f5f9; box-shadow: 0 18px 40px rgba(2, 6, 23, .35);
  min-height: 240px;
}
.match-hero .px-loader, .match-hero .match-message { color: #cbd5e1; min-height: 240px; }
.mh__league {
  display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 8px 10px;
  padding: 14px 16px 0; font-size: .85rem; font-weight: 700; color: #94a3b8; text-align: center;
}
.mh__league img { width: 22px; height: 22px; object-fit: contain; }
.mh__league b { color: #e2e8f0; }
.mh__teams { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; gap: 12px; padding: 22px 16px 14px; }
.mh__team { display: grid; justify-items: center; gap: 10px; text-align: center; min-width: 0; }
.mh__logo {
  width: 84px; height: 84px; border-radius: 50%; display: grid; place-items: center;
  background: rgba(255, 255, 255, .06); border: 1px solid rgba(255, 255, 255, .12);
  box-shadow: 0 0 0 6px rgba(255, 255, 255, .02);
}
.mh__logo img { width: 58px; height: 58px; object-fit: contain; }
.mh__logo span { font-weight: 800; color: #94a3b8; }
.mh__name { font-size: 1.05rem; font-weight: 800; line-height: 1.4; overflow-wrap: anywhere; }
.mh__center { display: grid; justify-items: center; gap: 10px; min-width: 120px; }
.mh__score { display: inline-flex; align-items: center; gap: 12px; font-size: 2.6rem; font-weight: 900; line-height: 1; letter-spacing: 1px; }
.mh__score .sep { color: #475569; font-size: 1.8rem; }
.match-hero--live .mh__score { color: #32CD32; text-shadow: 0 0 22px rgba(50, 205, 50, .35); }
.mh__time { direction: ltr; font-size: 2rem; font-weight: 900; padding: 4px 16px; border-radius: 12px; background: rgba(255, 255, 255, .06); }
.mh__badge { display: inline-flex; align-items: center; gap: 6px; padding: 3px 12px; border-radius: 999px; font-size: .78rem; font-weight: 800; background: rgba(255, 255, 255, .08); color: #cbd5e1; }
.mh__badge--live { background: rgba(255, 59, 92, .16); color: #ff5c78; }
.mh__badge--live::before { content: ''; width: 7px; height: 7px; border-radius: 50%; background: #ff3b5c; animation: pxl-pulse 1.6s infinite; }
.mh__ht { font-size: .8rem; color: #94a3b8; }
.mh__meta {
  list-style: none; margin: 0; padding: 12px 16px 16px;
  display: flex; flex-wrap: wrap; justify-content: center; gap: 8px;
  border-top: 1px solid rgba(255, 255, 255, .06);
}
.mh__meta li {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 12px; border-radius: 999px; font-size: .8rem; font-weight: 700;
  background: rgba(255, 255, 255, .05); border: 1px solid rgba(255, 255, 255, .07); color: #cbd5e1;
}
.mh__meta svg { width: 15px; height: 15px; color: #32CD32; flex: 0 0 auto; }
@media (max-width: 520px) {
  .mh__logo { width: 64px; height: 64px; } .mh__logo img { width: 44px; height: 44px; }
  .mh__name { font-size: .92rem; } .mh__score { font-size: 2rem; } .mh__time { font-size: 1.5rem; }
  .mh__center { min-width: 92px; }
}

.match-tabs {
  display: flex; gap: 6px; padding: 6px; border-radius: 999px;
  background: #0f172a; border: 1px solid #334155; position: sticky; top: 70px; z-index: 5;
}
.match-tab {
  flex: 1 1 0; padding: 10px 14px; border: 0; border-radius: 999px; cursor: pointer;
  background: transparent; color: #cbd5e1; font: inherit; font-weight: 800; font-size: .92rem;
  transition: background-color .2s, color .2s, box-shadow .2s;
}
.match-tab:hover { color: #fff; }
.match-tab.is-active { background: #32CD32; color: #04120a; box-shadow: 0 0 16px rgba(50, 205, 50, .4); }
.match-tab:focus-visible { outline: 2px solid #32CD32; outline-offset: 2px; }
.match-panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); padding: 16px; min-height: 180px; animation: px-fade-in .3s ease both; }
.match-panel[hidden] { display: none; }
.match-panel .match-message { padding: 40px 12px; }

/* Events timeline: home side | minute | away side (RTL: home on the right) */
.ev-list { list-style: none; margin: 0; padding: 0; position: relative; }
.ev-list::before { content: ''; position: absolute; inset-block: 0; inset-inline-start: 50%; width: 2px; transform: translateX(50%); background: var(--border); }
.ev { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) 54px minmax(0, 1fr); align-items: center; gap: 10px; padding: 7px 0; }
.ev__min {
  grid-column: 2; justify-self: center; z-index: 1;
  min-width: 46px; padding: 3px 6px; border-radius: 999px; text-align: center;
  background: var(--surface-2); border: 1px solid var(--border); font-size: .78rem; font-weight: 800;
}
.ev__body { display: flex; align-items: center; gap: 10px; min-width: 0; padding: 8px 12px; border-radius: 12px; background: var(--surface-2); }
.ev--home .ev__body { grid-column: 1; grid-row: 1; justify-self: end; flex-direction: row-reverse; text-align: end; }
.ev--away .ev__body { grid-column: 3; grid-row: 1; justify-self: start; }
.ev__icon { flex: 0 0 auto; width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; background: var(--surface); }
.ev__icon svg { width: 16px; height: 16px; }
.ev__txt { display: grid; gap: 2px; min-width: 0; }
.ev__txt b { font-size: .9rem; overflow-wrap: anywhere; }
.ev__txt small { color: var(--text-muted); font-size: .76rem; }
.ev--goal .ev__body { background: rgba(50, 205, 50, .12); box-shadow: inset 0 0 0 1px rgba(50, 205, 50, .35); }
.ev--goal .ev__icon { color: var(--brand-strong); }
.ev__in { color: #16a34a; } .ev__out { color: #e11d48; }
.card-ico { display: inline-block; width: 11px; height: 15px; border-radius: 2px; }
.card-ico--y { background: #facc15; } .card-ico--r { background: #e11d48; }
.card-ico--yr { background: linear-gradient(135deg, #facc15 50%, #e11d48 50%); }
.ev.ev--period { grid-template-columns: 1fr; }
.ev--period .ev__period {
  justify-self: center; z-index: 1; padding: 5px 14px; white-space: nowrap; border-radius: 999px;
  background: #0f172a; color: #e2e8f0; border: 1px solid #334155; font-size: .78rem; font-weight: 800;
}
.ev--period .ev__period b { color: #32CD32; margin-inline-start: 8px; display: inline-block; }
@media (max-width: 520px) { .ev { grid-template-columns: minmax(0, 1fr) 46px minmax(0, 1fr); gap: 6px; } .ev__body { padding: 6px 8px; gap: 6px; } .ev__icon { width: 24px; height: 24px; } }

/* Lineups */
.lu-grid { display: grid; gap: 16px; }
@media (min-width: 900px) { .lu-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.lu-team { display: grid; gap: 12px; align-content: start; }
.lu-head { display: flex; align-items: center; gap: 10px; font-weight: 800; }
.lu-head img { width: 30px; height: 30px; object-fit: contain; }
.lu-formation { margin-inline-start: auto; padding: 3px 10px; border-radius: 999px; background: #0f172a; color: #32CD32; border: 1px solid #334155; font-size: .8rem; direction: ltr; }
.pitch {
  position: relative; display: flex; flex-direction: column-reverse; justify-content: space-between; gap: 10px;
  min-height: 420px; padding: 18px 8px; border-radius: 14px; overflow: hidden;
  background:
    linear-gradient(rgba(255, 255, 255, .14), rgba(255, 255, 255, .14)) center / 100% 2px no-repeat,
    repeating-linear-gradient(0deg, #14532d 0 42px, #166534 42px 84px);
  border: 2px solid rgba(255, 255, 255, .18);
}
.pitch::before { content: ''; position: absolute; left: 50%; top: 50%; width: 90px; height: 90px; border: 2px solid rgba(255, 255, 255, .14); border-radius: 50%; transform: translate(-50%, -50%); }
.pitch__line { position: relative; display: flex; justify-content: space-around; gap: 4px; }
.pl { display: grid; justify-items: center; gap: 4px; width: 72px; text-align: center; color: #fff; }
.pl__num {
  position: relative; width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center;
  background: #0f172a; border: 2px solid #32CD32; font-weight: 900; font-size: .85rem;
}
.pl--gk .pl__num { border-color: #facc15; }
.pl__name { font-size: .72rem; font-weight: 800; line-height: 1.3; text-shadow: 0 1px 2px rgba(0, 0, 0, .6); overflow-wrap: anywhere; }
.pl__tags { display: flex; gap: 3px; justify-content: center; min-height: 14px; }
.pl__rating { position: absolute; top: -8px; inset-inline-end: -14px; padding: 0 4px; border-radius: 6px; font-size: .62rem; font-weight: 800; background: #32CD32; color: #04120a; }
.pl__cap { position: absolute; bottom: -6px; inset-inline-start: -8px; width: 16px; height: 16px; border-radius: 50%; font-size: .6rem; display: grid; place-items: center; background: #facc15; color: #0f172a; font-weight: 900; }
.tag-goal { font-size: .7rem; } .tag-sub { color: #fda4af; font-size: .7rem; }
.lu-sub-title { margin: 4px 0 0; font-size: .92rem; font-weight: 800; }
.lu-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.lu-list li { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px; background: var(--surface-2); font-size: .88rem; }
.lu-list .n { flex: 0 0 auto; width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; background: var(--surface); border: 1px solid var(--border); font-weight: 800; font-size: .78rem; }
.lu-list .meta { margin-inline-start: auto; display: inline-flex; align-items: center; gap: 6px; color: var(--text-muted); font-size: .76rem; }
.lu-list .r { padding: 1px 6px; border-radius: 6px; background: var(--brand-soft); color: var(--brand-strong); font-weight: 800; }
.lu-coach { margin: 0; color: var(--text-muted); font-size: .85rem; }
.lu-coach b { color: var(--text); }
.post-labels { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 20px; }

/* Sidebar */
.sidebar { display: grid; gap: 18px; align-content: start; }
.sidebar .widget { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; box-shadow: var(--shadow); }
.widget-title { margin: 0 0 12px; font-size: 1.02rem; font-weight: 800; display: flex; align-items: center; gap: 8px; }
.widget-title::before { content: ''; width: 4px; height: 18px; border-radius: 3px; background: var(--brand); }
@media (min-width: 1024px) { .sidebar { position: sticky; top: calc(var(--header-h) + 16px); } }
.standings { width: 100%; border-collapse: collapse; font-size: .88rem; }
.standings th, .standings td { padding: 8px 6px; text-align: center; border-bottom: 1px solid var(--border); }
.standings th { color: var(--text-muted); font-weight: 700; font-size: .78rem; }
.standings td:nth-child(2), .standings th:nth-child(2) { text-align: start; }
.standings tr:last-child td { border-bottom: 0; }
.standings .pos { width: 26px; font-weight: 800; }
.standings tr.top .pos { color: var(--brand-strong); }
[data-theme="dark"] .standings tr.top .pos { color: var(--brand); }
.standings .pts { font-weight: 800; }
.standings .team-cell { display: flex; align-items: center; gap: 8px; min-width: 0; }
.standings .team-cell img { width: 20px; height: 20px; object-fit: contain; flex-shrink: 0; }
.standings .team-cell span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.standings .diff { direction: ltr; }
.standings tr.standings-state td { padding: 22px 6px; color: var(--text-muted); font-size: .82rem; }
.px-mini-spinner {
  display: inline-block; width: 26px; height: 26px; border-radius: 50%;
  border: 3px solid rgba(50, 205, 50, 0.2); border-top-color: #32CD32;
  animation: px-mini-spin .8s linear infinite;
}
@keyframes px-mini-spin { to { transform: rotate(360deg); } }
/* Standings page */
.standings-page { display: grid; gap: 18px; }
.standings-page__head .section-title { margin-bottom: 4px; }
.standings-page__sub { margin: 0; color: var(--text-muted); font-size: .92rem; }
.league-filter {
  display: flex; gap: 8px; overflow-x: auto; scroll-snap-type: x proximity;
  padding: 10px; border-radius: var(--radius);
  background: #0f172a; border: 1px solid #334155;
  scrollbar-width: thin; scrollbar-color: #334155 transparent;
}
.league-filter::-webkit-scrollbar { height: 6px; }
.league-filter::-webkit-scrollbar-thumb { background: #334155; border-radius: 3px; }
.league-chip {
  flex: 0 0 auto; scroll-snap-align: start;
  padding: 8px 16px; border-radius: 999px;
  border: 1px solid #334155; background: #1e293b; color: #cbd5e1;
  font: inherit; font-size: .88rem; font-weight: 700; white-space: nowrap; cursor: pointer;
  transition: background-color .2s, color .2s, border-color .2s, box-shadow .2s;
}
.league-chip:hover { border-color: #32CD32; color: #fff; }
.league-chip.is-active { background: #32CD32; border-color: #32CD32; color: #04120a; box-shadow: 0 0 16px rgba(50, 205, 50, .45); }
.league-chip:focus-visible { outline: 2px solid #32CD32; outline-offset: 2px; }

.standings-board { min-height: 260px; }
.standings-loading, .standings-message {
  display: grid; justify-items: center; gap: 12px;
  padding: 60px 16px; color: var(--text-muted); font-weight: 700; text-align: center;
}
.standings-board.is-ready .standings-card { animation: px-fade-in .35s ease both; }
@keyframes px-fade-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.standings-card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow); overflow: hidden; margin-bottom: 16px;
}
.standings-card__head {
  display: flex; align-items: center; gap: 10px;
  padding: 12px 16px; background: var(--surface-2); border-bottom: 1px solid var(--border);
  font-weight: 800;
}
.standings-card__head img { width: 26px; height: 26px; object-fit: contain; }
.standings-card__head small { white-space: nowrap; margin-inline-start: auto; color: var(--text-muted); font-weight: 700; font-size: .78rem; }
.standings-scroll { overflow-x: auto; }
.standings--full { min-width: 100%; font-size: .9rem; }
.standings--full th, .standings--full td { padding: 10px 8px; white-space: nowrap; }
.standings--full td:nth-child(2) { min-width: 150px; }
.standings--full tbody tr { transition: background-color .15s; }
.standings--full tbody tr:hover { background: var(--brand-soft); }
.standings--full td.pos { position: relative; }
.standings--full tr[data-zone] td.pos { box-shadow: inset -4px 0 0 var(--zone); }   /* RTL: start edge */
.standings--full .team-cell img { width: 24px; height: 24px; }
@media (max-width: 640px) { .standings--full .col-optional { display: none; } }
.standings-legend { display: flex; flex-wrap: wrap; gap: 8px 18px; padding: 12px 16px; border-top: 1px solid var(--border); font-size: .8rem; color: var(--text-muted); }
.standings-legend span { display: inline-flex; align-items: center; gap: 6px; }
.standings-legend i { width: 10px; height: 10px; border-radius: 3px; display: inline-block; }

.standings-retry {
  margin-top: 8px; padding: 4px 14px; border: 0; border-radius: 999px;
  background: #32CD32; color: #04120a; font: inherit; font-weight: 800; cursor: pointer;
}

/* ==========================================================================
   6b. Portal blocks: header social, app card, community banner, news placeholder
   ========================================================================== */
.header-social { display: flex; align-items: center; gap: 6px; }
.icon-btn.is-telegram:hover { color: #229ED9; border-color: #229ED9; box-shadow: 0 0 14px rgba(34, 158, 217, .35); }
.icon-btn.is-whatsapp:hover { color: #25D366; border-color: #25D366; box-shadow: 0 0 14px rgba(37, 211, 102, .35); }
@media (max-width: 420px) { .header-social { display: none; } }   /* footer + banner keep the links on small phones */

/* App download card: always dark with the lime accent */
.app-card {
  position: relative; overflow: hidden;
  padding: 20px 18px;
  border-radius: var(--radius);
  background: radial-gradient(120% 90% at 100% 0%, rgba(50, 205, 50, .22) 0%, rgba(50, 205, 50, 0) 55%), linear-gradient(160deg, #0f172a 0%, #1e293b 100%);
  border: 1px solid #334155;
  box-shadow: 0 10px 30px rgba(2, 6, 23, .35);
  color: #f1f5f9;
  scroll-margin-top: calc(var(--header-h) + 16px);
}
.app-card__title { margin: 0 0 6px; font-size: 1.1rem; font-weight: 800; display: flex; align-items: center; gap: 8px; color: #fff; }
.app-card__title::before { content: ''; width: 4px; height: 20px; border-radius: 3px; background: #32CD32; box-shadow: 0 0 14px rgba(50, 205, 50, .6); }
.app-card__text { margin: 0 0 16px; color: #94a3b8; font-size: .88rem; line-height: 1.6; }
.app-card__badges { display: grid; gap: 10px; }
.store-badge {
  display: flex; align-items: center; gap: 12px;
  padding: 10px 14px; border-radius: 12px;
  background: #0b1220; border: 1px solid #334155; color: #f8fafc;
  transition: border-color .2s, box-shadow .2s, transform .15s;
}
.store-badge:hover { border-color: #32CD32; box-shadow: 0 0 18px rgba(50, 205, 50, .35); transform: translateY(-2px); color: #fff; }
.store-badge svg { width: 26px; height: 26px; flex-shrink: 0; }
.store-badge__text { display: flex; flex-direction: column; line-height: 1.25; }
.store-badge__text small { font-size: .7rem; color: #94a3b8; font-weight: 600; }
.store-badge__text strong { font-size: 1.02rem; font-weight: 800; direction: ltr; text-align: right; }

/* Community banner (home, below the matches) */
.community-banner {
  margin-top: 26px;
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 18px;
  padding: 22px 24px;
  border-radius: calc(var(--radius) + 4px);
  background: radial-gradient(90% 140% at 0% 50%, rgba(50, 205, 50, .18) 0%, rgba(50, 205, 50, 0) 60%), linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  border: 1px solid #334155;
  box-shadow: 0 10px 30px rgba(2, 6, 23, .25);
  color: #f1f5f9;
}
.community-banner__text { display: flex; align-items: center; gap: 14px; min-width: 0; }
.community-banner__icon {
  width: 46px; height: 46px; flex-shrink: 0; border-radius: 14px;
  display: grid; place-items: center; background: rgba(50, 205, 50, .15); color: #32CD32;
}
.community-banner__icon svg { width: 24px; height: 24px; }
.community-banner h2 { margin: 0; font-size: 1.08rem; font-weight: 800; line-height: 1.5; color: #fff; }
.community-banner p { margin: 2px 0 0; color: #94a3b8; font-size: .86rem; }
.community-banner__actions { display: flex; flex-wrap: wrap; gap: 10px; }
.btn-social {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 10px 18px; border-radius: 999px;
  font-weight: 800; font-size: .92rem; color: #fff;
  transition: transform .15s, box-shadow .2s, filter .2s;
}
.btn-social svg { width: 18px; height: 18px; }
.btn-social:hover { transform: translateY(-2px); color: #fff; filter: brightness(1.08); }
.btn-social--telegram { background: #229ED9; box-shadow: 0 6px 18px rgba(34, 158, 217, .35); }
.btn-social--whatsapp { background: #25D366; color: #06240f; box-shadow: 0 6px 18px rgba(37, 211, 102, .35); }
.btn-social--whatsapp:hover { color: #06240f; }
@media (max-width: 600px) {
  .community-banner { padding: 18px; }
  .community-banner__actions { width: 100%; }
  .btn-social { flex: 1 1 0; justify-content: center; }
}

/* Latest news placeholder (shown while the blog has no posts) */
.news-placeholder .card { pointer-events: none; }
.news-placeholder .card:hover { transform: none; box-shadow: var(--shadow); border-color: var(--border); }
.skeleton-block {
  display: block; border-radius: 8px;
  background: linear-gradient(90deg, var(--surface-2) 0%, var(--border) 50%, var(--surface-2) 100%);
  background-size: 200% 100%;
  animation: px-shimmer 1.4s ease-in-out infinite;
}
.news-placeholder .card__media .skeleton-block { position: absolute; inset: 0; border-radius: 0; }
.skeleton-line { height: 12px; }
.skeleton-line--title { height: 16px; width: 85%; }
.skeleton-line--short { width: 55%; }
.skeleton-tag { width: 64px; height: 20px; border-radius: 999px; }
@keyframes px-shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }
.news-placeholder__note { margin: 14px 0 0; text-align: center; color: var(--text-muted); font-size: .85rem; }

/* ==========================================================================
   7. Footer
   ========================================================================== */
.site-footer { background: var(--surface); border-top: 1px solid var(--border); padding-top: 40px; }
[data-theme="dark"] .site-footer { background: #05070a; }
.footer-grid { display: grid; grid-template-columns: 1fr; gap: 28px; }
@media (min-width: 640px) { .footer-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .footer-grid { grid-template-columns: 1.4fr 1fr 1fr 1fr; } }
.footer-col h3 { margin: 0 0 12px; font-size: 1rem; font-weight: 800; }
.footer-col p { margin: 0; color: var(--text-muted); font-size: .92rem; }
.footer-links { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.footer-links a { color: var(--text-muted); font-size: .92rem; }
.footer-links a:hover { color: var(--brand-strong); }
.social { display: flex; flex-wrap: wrap; gap: 10px; }
.social a {
  width: 40px; height: 40px; display: grid; place-items: center; border-radius: 12px;
  border: 1px solid var(--border); background: var(--surface-2);
  transition: border-color .2s, box-shadow .2s, color .2s;
}
.social a:hover { border-color: var(--brand); color: var(--brand-strong); box-shadow: var(--brand-glow); }
.social svg { width: 18px; height: 18px; }
.social a.is-telegram:hover { color: #229ED9; border-color: #229ED9; }
.social a.is-whatsapp:hover { color: #25D366; border-color: #25D366; }
.footer-apps { display: grid; gap: 8px; margin-top: 14px; }
.footer-apps a { display: inline-flex; align-items: center; gap: 8px; color: var(--text-muted); font-size: .9rem; }
.footer-apps a:hover { color: var(--brand-strong); }
.footer-apps svg { width: 18px; height: 18px; }
.footer-bottom {
  margin-top: 32px; padding-block: 18px; border-top: 1px solid var(--border);
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px;
  color: var(--text-muted); font-size: .85rem;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
}

head.b:template-skin:
body#layout { background: #f6f7f9; font-family: Arial, sans-serif; }
body#layout .header-inner, body#layout .main-nav, body#layout .header-actions,
body#layout .fixtures, body#layout .arena-head, body#layout .player-frame { display: none; }
body#layout .arena-grid, body#layout .content-wrap, body#layout .footer-grid { display: flex; gap: 8px; }
body#layout .arena-center, body#layout .content-main, body#layout .footer-grid > * { flex: 1; }
body#layout .ad-side { display: block; width: 160px; }
body#layout .sidebar { width: 320px; }

body.script:
//
(function () {
  var root = document.documentElement;
  var toggle = document.getElementById('theme-toggle');
  function applyTheme(theme) {
    root.setAttribute('data-theme', theme);
    toggle.setAttribute('aria-pressed', theme === 'dark' ? 'true' : 'false');
    var meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute('content', theme === 'dark' ? '#07090c' : '#32cd32');
  }
  applyTheme(root.getAttribute('data-theme') === 'dark' ? 'dark' : 'light');
  toggle.addEventListener('click', function () {
    var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    applyTheme(next);
    try { localStorage.setItem('pxl-theme', next); } catch (e) {}
  });

  var menuBtn = document.getElementById('menu-toggle');
  var nav = document.getElementById('main-nav');
  function setMenu(open) {
    nav.classList.toggle('is-open', open);
    menuBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
    menuBtn.setAttribute('aria-label', open ? 'إغلاق القائمة' : 'فتح القائمة');
  }
  menuBtn.addEventListener('click', function () { setMenu(!nav.classList.contains('is-open')); });
  nav.addEventListener('click', function (e) { if (e.target.closest('a')) setMenu(false); });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') setMenu(false); });
  window.addEventListener('resize', function () { if (window.innerWidth > 860) setMenu(false); });

  var y = document.getElementById('pxl-year');
  if (y) y.textContent = String(new Date().getFullYear());
})();
//

b:if.script:
//
(function () {
  'use strict';

  var WORKER_BASE_URL = window.PXL_WORKER_BASE_URL || '';
  var STANDINGS_PATH = '/api/standings/{id}?include=results';
  var TEAM_LOGO_BASE = 'https://imgs.ysscores.com/teams/128/';

  var board = document.getElementById('standings-board');
  var filter = document.getElementById('league-filter');
  if (!board || !filter) return;
  var chips = Array.prototype.slice.call(filter.querySelectorAll('.league-chip'));

  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function pick() {
    for (var i = 0; i < arguments.length; i++) if (arguments[i] != null && arguments[i] !== '') return arguments[i];
    return '';
  }
  function imgUrl(value) {
    var v = String(value || '').trim();
    if (/^https:\/\//i.test(v)) return v;
    return /^[\w.-]+\.(png|jpe?g|webp|gif|svg)$/i.test(v) ? TEAM_LOGO_BASE + encodeURIComponent(v) : '';
  }
  function safeColor(c) { return /^#[0-9a-f]{3,8}$/i.test(String(c || '')) ? c : ''; }

  // ------------------------------------------------------------------ parsing
  function parseRow(r, i) {
    var zone = r.zone && typeof r.zone === 'object' ? r.zone : {};
    var diff = pick(r.goalDiff, r.diff, r.goal_difference,
      (r.goalsFor != null && r.goalsAgainst != null) ? Number(r.goalsFor) - Number(r.goalsAgainst) : 0);
    return {
      rank: Number(pick(r.rank, r.position, i + 1)) || i + 1,
      name: pick(r.teamName, r.team_name && r.team_name.short_title, r.name),
      logo: imgUrl(pick(r.teamLogo, r.team_name && r.team_name.image, r.logo)),
      played: pick(r.played, r.play, 0),
      won: pick(r.won, r.win, 0),
      drawn: pick(r.drawn, r.draw, 0),
      lost: pick(r.lost, r.lose, 0),
      gf: pick(r.goalsFor, r.for, 0),
      ga: pick(r.goalsAgainst, r.against, 0),
      diff: Number(diff) || 0,
      points: pick(r.points, r.pts, 0),
      zoneColor: safeColor(zone.color),
      zoneLabel: zone.label || ''
    };
  }
  function parseResponse(json) {
    var groups = Array.isArray(json && json.groups) ? json.groups : [];
    return {
      league: (json && json.league) || '',
      logo: imgUrl(json && json.leagueLogo),
      groups: groups.map(function (g) {
        return {
          name: g.name || g.title || '',
          rows: (Array.isArray(g.rows) ? g.rows : []).map(parseRow).sort(function (a, b) { return a.rank - b.rank; })
        };
      }).filter(function (g) { return g.rows.length; })
    };
  }

  // ------------------------------------------------------------------ rendering
  function rowHtml(t) {
    var diffText = t.diff > 0 ? '+' + t.diff : String(t.diff);
    return `<tr${t.zoneColor ? ` data-zone style="--zone:${esc(t.zoneColor)}" title="${esc(t.zoneLabel)}"` : ''}>
      <td class="pos">${esc(t.rank)}</td>
      <td><span class="team-cell">${t.logo ? `<img src="${esc(t.logo)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}<span>${esc(t.name)}</span></span></td>
      <td>${esc(t.played)}</td>
      <td class="col-optional">${esc(t.won)}</td>
      <td class="col-optional">${esc(t.drawn)}</td>
      <td class="col-optional">${esc(t.lost)}</td>
      <td class="col-optional">${esc(t.gf)}</td>
      <td class="col-optional">${esc(t.ga)}</td>
      <td class="diff" dir="ltr">${esc(diffText)}</td>
      <td class="pts">${esc(t.points)}</td>
    </tr>`;
  }
  function legendHtml(rows) {
    var seen = {};
    var items = [];
    rows.forEach(function (t) {
      if (t.zoneColor && t.zoneLabel && !seen[t.zoneLabel]) {
        seen[t.zoneLabel] = true;
        items.push(`<span><i style="background:${esc(t.zoneColor)}"></i>${esc(t.zoneLabel)}</span>`);
      }
    });
    return items.length ? `<div class="standings-legend">${items.join('')}</div>` : '';
  }
  function render(data) {
    if (!data.groups.length) { message('لا يتوفر جدول الترتيب لهذا الدوري حاليًا.', false); return; }
    var multi = data.groups.length > 1;
    board.innerHTML = data.groups.map(function (g) {
      return `
        <article class="standings-card">
          <div class="standings-card__head">
            ${data.logo ? `<img src="${esc(data.logo)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}
            <span>${esc(multi && g.name ? data.league + ' – ' + g.name : data.league)}</span>
            <small>${g.rows.length} فريقًا</small>
          </div>
          <div class="standings-scroll">
            <table class="standings standings--full">
              <thead><tr>
                <th>#</th><th>الفريق</th><th>لعب</th>
                <th class="col-optional">فوز</th><th class="col-optional">تعادل</th><th class="col-optional">خسارة</th>
                <th class="col-optional">له</th><th class="col-optional">عليه</th>
                <th>+/-</th><th>نقاط</th>
              </tr></thead>
              <tbody>${g.rows.map(rowHtml).join('')}</tbody>
            </table>
          </div>
          ${legendHtml(g.rows)}
        </article>`;
    }).join('');
    board.classList.add('is-ready');
  }
  function loading() {
    board.classList.remove('is-ready');
    board.innerHTML = '<div class="standings-loading" role="status"><span class="px-mini-spinner"></span><span>جاري تحميل الترتيب...</span></div>';
  }
  function message(text, retryId) {
    board.classList.remove('is-ready');
    board.innerHTML = `<div class="standings-message"><span>${esc(text)}</span>${retryId ? '<button class="standings-retry" type="button">إعادة المحاولة</button>' : ''}</div>`;
    var btn = board.querySelector('.standings-retry');
    if (btn) btn.addEventListener('click', function () { fetchStandings(retryId); });
  }

  // ------------------------------------------------------------------ fetching
  var cache = {};                     // id -> parsed data (instant switching back)
  var requestSeq = 0;

  async function fetchStandings(championshipId) {
    var id = String(championshipId);
    var mySeq = ++requestSeq;           // ignore responses for a league the user already left
    if (cache[id]) { render(cache[id]); return; }
    loading();
    if (!WORKER_BASE_URL || WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1) {
      console.error('[PX League] Set PXL_WORKER_BASE_URL (top of the theme) to load the standings.');
      return;                            // keep the spinner
    }
    var url = WORKER_BASE_URL + STANDINGS_PATH.replace('{id}', encodeURIComponent(id));
    for (var attempt = 1; attempt <= 3; attempt++) {
      var ctrl = new AbortController();
      var timer = setTimeout(function () { ctrl.abort(); }, 10000);
      try {
        var res = await fetch(url, { headers: { Accept: 'application/json' }, signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        var data = parseResponse(await res.json());
        cache[id] = data;
        if (mySeq === requestSeq) render(data);
        return;
      } catch (err) {
        if (attempt === 3) {
          console.warn('[PX League] standings:', err);
          if (mySeq === requestSeq) message('تعذّر تحميل الترتيب حاليًا.', id);
        } else {
          await new Promise(function (r) { setTimeout(r, 1000 * attempt); });
        }
      } finally {
        clearTimeout(timer);
      }
    }
  }

  // ------------------------------------------------------------------ league filter
  function selectLeague(chip, updateUrl) {
    chips.forEach(function (c) {
      var on = c === chip;
      c.classList.toggle('is-active', on);
      c.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    chip.scrollIntoView({ block: 'nearest', inline: 'center', behavior: 'smooth' });
    if (updateUrl) {
      try { history.replaceState(null, '', '#league=' + chip.getAttribute('data-id')); } catch (e) {}
    }
    fetchStandings(chip.getAttribute('data-id'));
  }
  filter.addEventListener('click', function (e) {
    var chip = e.target.closest('.league-chip');
    if (chip && !chip.classList.contains('is-active')) selectLeague(chip, true);
  });
  filter.addEventListener('keydown', function (e) {   // arrow keys move between leagues
    var i = chips.indexOf(document.activeElement);
    if (i === -1 || (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight')) return;
    e.preventDefault();
    var step = e.key === 'ArrowLeft' ? 1 : -1;           // RTL: left = next
    var next = chips[(i + step + chips.length) % chips.length];
    next.focus();
    selectLeague(next, true);
  });

  window.fetchStandings = fetchStandings;

  // Initial league: #league=ID in the URL, otherwise the first chip
  var m = /league=(\d+)/.exec(location.hash);
  var initial = (m && chips.filter(function (c) { return c.getAttribute('data-id') === m[1]; })[0]) || chips[0];
  selectLeague(initial, false);
})();
//

//
(function () {
  'use strict';

  var WORKER_BASE_URL = window.PXL_WORKER_BASE_URL || '';
  var TEAM_LOGO_BASE = 'https://imgs.ysscores.com/teams/128/';
  var LEAGUE_LOGO_BASE = 'https://imgs.ysscores.com/championship/64/';
  var LIVE_WINDOW_MS = 3.5 * 60 * 60 * 1000;
  var REFRESH_MS = 30 * 1000;

  var page = document.getElementById('match-page');
  if (!page) return;
  var hero = document.getElementById('match-hero');
  var panels = { events: document.getElementById('match-tab-events'), lineups: document.getElementById('match-tab-lineups') };
  var tabs = Array.prototype.slice.call(page.querySelectorAll('.match-tab'));

  // ------------------------------------------------------------------ helpers
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
  function imageUrl(base, file) {
    var f = file ? String(file).trim() : '';
    return /^[\w.-]+\.(png|jpe?g|webp|gif|svg)$/i.test(f) ? base + encodeURIComponent(f) : '';
  }
  function nameOf(x) {                                         // player / referee objects or plain strings
    if (!x) return '';
    if (typeof x === 'string') return x;
    return x.short_title || x.title || x.full_title || '';
  }
  function cairo(unix, opts) {
    try { return new Intl.DateTimeFormat('ar-EG', Object.assign({ timeZone: 'Africa/Cairo' }, opts)).format(new Date(unix * 1000)); }
    catch (e) { return ''; }
  }
  function cairoTime(unix) {
    if (!unix) return '--:--';
    return new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(unix * 1000));
  }
  function api(kind, id) { return WORKER_BASE_URL + '/api/matches/' + kind + '/' + encodeURIComponent(id) + '/D/60'; }

  async function fetchJson(url, attempts) {
    for (var i = 1; ; i++) {
      var ctrl = new AbortController();
      var timer = setTimeout(function () { ctrl.abort(); }, 10000);
      try {
        var res = await fetch(url, { headers: { Accept: 'application/json' }, cache: 'no-store', signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        var json = await res.json();
        if (json && json.status === false) throw new Error(json.message || 'API status false');
        return json && json.data != null ? json.data : json;
      } catch (err) {
        if (i >= attempts) throw err;
        await wait(1000 * i);
      } finally {
        clearTimeout(timer);
      }
    }
  }

  // Same rules as the home cards: 0 upcoming, 4 finished, other codes live near kick-off
  function statusOf(d) {
    var s = Number(d.status);
    if (s === 0) return 'upcoming';
    if (s === 4) return 'finished';
    var k = Number(d.match_timestamp) * 1000, now = Date.now();
    return k && now >= k - 10 * 60 * 1000 && now <= k + LIVE_WINDOW_MS ? 'live' : 'other';
  }
  // 'minutes' = seconds since the current half started; status 1 = 1st half, 3 = 2nd half
  function liveMinute(status, seconds) {
    var secs = Number(seconds);
    if (!(secs > 0)) return '';
    var m = Math.floor(secs / 60) + 1, st = Number(status);
    if (st === 1) return m > 45 ? '45+' + (m - 45) : String(m);
    if (st === 3) { var t = 45 + m; return t > 90 ? '90+' + (t - 90) : String(t); }
    return '';
  }

  // ------------------------------------------------------------------ icons
  var I = {
    ball: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m12 7 4 3-1.5 5h-5L8 10z" fill="currentColor"/></svg>',
    sub: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path class="ev__in" d="M7 20V8m0 0-4 4m4-4 4 4"/><path class="ev__out" d="M17 4v12m0 0 4-4m-4 4-4-4"/></svg>',
    cal: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>',
    pin: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 22s7-6.1 7-12a7 7 0 0 0-14 0c0 5.9 7 12 7 12z"/><circle cx="12" cy="10" r="2.5"/></svg>',
    whistle: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="9" cy="14" r="6"/><path d="M13 9.5 21 6v4l-6.5 2"/></svg>',
    tv: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="m17 2-5 5-5-5"/></svg>',
    mic: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/><path d="M19 11a7 7 0 0 1-14 0M12 18v4"/></svg>'
  };
  function cardIcon(kind) { return '<span class="card-ico card-ico--' + kind + '"></span>'; }

  // ------------------------------------------------------------------ hero
  function teamBlock(t) {
    var logo = imageUrl(TEAM_LOGO_BASE, t.image);
    var name = t.full_title || t.title || '';
    return `<div class="mh__team">
        <span class="mh__logo">${logo ? `<img src="${esc(logo)}" alt="${esc(name)}" referrerpolicy="no-referrer" onerror="this.replaceWith(document.createTextNode(''))">` : `<span>${esc(name.slice(0, 2))}</span>`}</span>
        <span class="mh__name">${esc(name)}</span>
      </div>`;
  }
  function halfTimeScore(ev) {                                 // fh_scores: [{home_scores}, {away_scores}]
    var fh = ev && Array.isArray(ev.fh_scores) ? ev.fh_scores : null;
    if (!fh) return '';
    var h = fh.find(function (x) { return x && x.home_scores != null; });
    var a = fh.find(function (x) { return x && x.away_scores != null; });
    return h && a ? h.home_scores + ' - ' + a.away_scores : '';
  }
  function renderHero(d, ev) {
    var st = statusOf(d);
    var minute = st === 'live' ? liveMinute(d.status, d.minutes) : '';
    var champ = d.championship || {};
    var champLogo = imageUrl(LEAGUE_LOGO_BASE, champ.image);
    var center = st === 'upcoming' || st === 'other'
      ? `<span class="mh__time">${esc(cairoTime(Number(d.match_timestamp)))}</span>`
      : `<span class="mh__score"><span>${esc(d.home_scores != null ? d.home_scores : 0)}</span><span class="sep">-</span><span>${esc(d.away_scores != null ? d.away_scores : 0)}</span></span>`;
    var badge = st === 'live'
      ? `<span class="mh__badge mh__badge--live">مباشر${minute ? ` <span dir="ltr">${esc(minute)}'</span>` : ''}</span>`
      : `<span class="mh__badge">${st === 'finished' ? 'انتهت' : st === 'upcoming' ? 'لم تبدأ' : 'غير محدد'}</span>`;
    var ht = st !== 'upcoming' ? halfTimeScore(ev) : '';
    var cc = Array.isArray(d.channel_commm) && d.channel_commm.length ? d.channel_commm[0] : {};
    var ts = Number(d.match_timestamp);
    var meta = [
      ts ? [I.cal, cairo(ts, { weekday: 'long', day: 'numeric', month: 'long' }) + ' · ' + cairoTime(ts)] : null,
      d.Stadium ? [I.pin, d.Stadium] : null,
      nameOf(d.referees) ? [I.whistle, 'الحكم: ' + nameOf(d.referees)] : null,
      cc.channel_name ? [I.tv, cc.channel_name] : null,
      cc.commentator_name ? [I.mic, cc.commentator_name] : null
    ].filter(Boolean);

    hero.className = 'match-hero' + (st === 'live' ? ' match-hero--live' : '');
    hero.innerHTML = `
      <div class="mh__league">
        ${champLogo ? `<img src="${esc(champLogo)}" alt="" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}
        <b>${esc(champ.title || '')}</b>${d.round ? `<span>· ${esc(d.round)}</span>` : ''}
      </div>
      <div class="mh__teams">
        ${teamBlock(d.home_team || {})}
        <div class="mh__center">${center}${badge}${ht ? `<span class="mh__ht">الشوط الأول: ${esc(ht)}</span>` : ''}</div>
        ${teamBlock(d.away_team || {})}
      </div>
      ${meta.length ? `<ul class="mh__meta">${meta.map(function (x) { return `<li>${x[0]}<span>${esc(x[1])}</span></li>`; }).join('')}</ul>` : ''}`;

    var home = (d.home_team && (d.home_team.full_title || d.home_team.title)) || '';
    var away = (d.away_team && (d.away_team.full_title || d.away_team.title)) || '';
    if (home && away) document.title = home + ' ضد ' + away + ' | ' + (document.title.split(' | ').pop() || 'PX League');
    return st;
  }

  // ------------------------------------------------------------------ events tab
  var PERIODS = { 1: 'انطلاق المباراة', 2: 'نهاية الشوط الأول', 3: 'بداية الشوط الثاني', 4: 'نهاية المباراة' };
  function minuteText(e) {
    var m = Number(e.time_minute), p = Number(e.time_plus);
    if (!(m >= 0)) return '';
    return m + (p > 0 ? '+' + p : '') + "'";
  }
  function eventHtml(e, homeId, awayId, ev) {
    var type = Number(e.type);
    if (type === 100) {
      var label = PERIODS[e.status];
      if (!label) return '';
      var score = '';
      if (Number(e.status) === 2) score = halfTimeScore(ev);
      if (Number(e.status) === 4) score = (ev.home_scores != null ? ev.home_scores : 0) + ' - ' + (ev.away_scores != null ? ev.away_scores : 0);
      return `<li class="ev ev--period"><span class="ev__period">${esc(label)}${score ? `<b>${esc(score)}</b>` : ''}</span></li>`;
    }
    var side = String(e.team_id) === String(homeId) ? 'home' : String(e.team_id) === String(awayId) ? 'away' : '';
    if (!side) return '';
    var player = nameOf(e.player_name), assist = nameOf(e.assist_player_name);
    var icon = '', title = player, sub = '', cls = '';
    if (type === 1 || type === 4 || type === 5) {
      cls = ' ev--goal'; icon = I.ball;
      sub = type === 4 ? 'هدف عكسي' : type === 5 ? 'ركلة جزاء' : assist ? 'صناعة: ' + assist : 'هدف';
    } else if (type === 2) {
      icon = cardIcon('y'); sub = 'بطاقة صفراء';
    } else if (type === 3) {
      var second = Number(e.status) === 7;
      icon = cardIcon(second ? 'yr' : 'r'); sub = second ? 'إنذار ثانٍ' : 'بطاقة حمراء';
    } else if (type === 8) {
      icon = I.sub;
      title = assist || player;                                // player coming on
      sub = (assist ? 'خروج: ' + player : 'تبديل') + (Number(e.status) === 9 ? ' (إصابة)' : '');
    } else {
      return '';                                               // unverified event code: not shown
    }
    if (!title) return '';
    return `<li class="ev ev--${side}${cls}">
        <div class="ev__body"><span class="ev__icon">${icon}</span><span class="ev__txt"><b>${esc(title)}</b>${sub ? `<small>${esc(sub)}</small>` : ''}</span></div>
        <span class="ev__min" dir="ltr">${esc(minuteText(e))}</span>
      </li>`;
  }
  function renderEvents(ev, info) {
    var list = ev && Array.isArray(ev.events) ? ev.events : [];
    var homeId = (info.home_team || {}).row_id, awayId = (info.away_team || {}).row_id;
    var html = list.map(function (e) { return eventHtml(e, homeId, awayId, ev); }).join('');   // API order: newest first
    panels.events.innerHTML = html
      ? `<ol class="ev-list">${html}</ol>`
      : `<div class="match-message"><span>${statusOf(info) === 'upcoming' ? 'لم تبدأ المباراة بعد، ستظهر الأحداث هنا فور انطلاقها.' : 'لا توجد أحداث مسجلة لهذه المباراة.'}</span></div>`;
  }

  // ------------------------------------------------------------------ lineups tab
  var LINE_ORDER = { G: 0, D: 1, M: 2, F: 3 };
  function tagsHtml(p) {
    var t = '';
    var goals = Number(p.goal) || 0;
    for (var i = 0; i < Math.min(goals, 3); i++) t += '<span class="tag-goal">⚽</span>';
    if (Number(p.red)) t += cardIcon('r');
    else if (Number(p.yellow)) t += cardIcon('y');
    if (Number(p.substitute)) t += '<span class="tag-sub" title="تم استبداله">▼</span>';
    return t;
  }
  function playerChip(p, isGk) {
    var pl = p.player || {};
    return `<div class="pl${isGk ? ' pl--gk' : ''}">
        <span class="pl__num">${esc(pl.player_number || '')}${p.rating ? `<span class="pl__rating">${esc(p.rating)}</span>` : ''}${Number(p.captain) ? '<span class="pl__cap">C</span>' : ''}</span>
        <span class="pl__name">${esc(nameOf(pl))}</span>
        <span class="pl__tags">${tagsHtml(p)}</span>
      </div>`;
  }
  // Formation "4-4-1-1" -> rows: [GK], [4], [4], [1], [1]; players ordered G, D, M, F then formation_position
  function pitchHtml(starters, formation) {
    var sorted = starters.slice().sort(function (a, b) {
      var la = LINE_ORDER[a.position] != null ? LINE_ORDER[a.position] : 9, lb = LINE_ORDER[b.position] != null ? LINE_ORDER[b.position] : 9;
      return la - lb || (Number(a.formation_position) || 0) - (Number(b.formation_position) || 0);
    });
    var gk = sorted.filter(function (p) { return p.position === 'G'; });
    var field = sorted.filter(function (p) { return p.position !== 'G'; });
    var lines = String(formation || '').split('-').map(Number).filter(function (n) { return n > 0; });
    var total = lines.reduce(function (a, b) { return a + b; }, 0);
    if (gk.length !== 1 || !lines.length || total !== field.length) return '';   // unknown shape: list only
    var rows = [gk], i = 0;
    lines.forEach(function (n) { rows.push(field.slice(i, i + n)); i += n; });
    return `<div class="pitch">${rows.map(function (r, idx) {
      return `<div class="pitch__line">${r.map(function (p) { return playerChip(p, idx === 0); }).join('')}</div>`;
    }).join('')}</div>`;
  }
  function listHtml(players) {
    return `<ul class="lu-list">${players.map(function (p) {
      var pl = p.player || {};
      return `<li><span class="n">${esc(pl.player_number || '-')}</span><span>${esc(nameOf(pl))}</span>
        <span class="meta">${tagsHtml(p)}${p.rating ? `<span class="r">${esc(p.rating)}</span>` : ''}</span></li>`;
    }).join('')}</ul>`;
  }
  function teamLineupHtml(team, data, side) {
    var tid = String(team.row_id || '');
    var lu = (data.lineup || {})[tid] || {};
    var starters = Array.isArray(lu.lineup) ? lu.lineup : [];
    var subs = Array.isArray(lu.substitutions) ? lu.substitutions : [];
    var injured = ((data.lineup_injureds || {})[tid]) || [];
    var meta = data['0'] || {};
    var formation = meta[side + '_formation'] || '';
    var coach = nameOf(meta[side + '_coach']);
    var logo = imageUrl(TEAM_LOGO_BASE, team.image);
    if (!starters.length) return '';
    var pitch = pitchHtml(starters, formation);
    return `<section class="lu-team">
        <div class="lu-head">${logo ? `<img src="${esc(logo)}" alt="" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}<span>${esc(team.full_title || team.title || '')}</span>${formation ? `<span class="lu-formation">${esc(formation)}</span>` : ''}</div>
        ${pitch || listHtml(starters)}
        ${coach ? `<p class="lu-coach">المدرب: <b>${esc(coach)}</b></p>` : ''}
        ${subs.length ? `<h3 class="lu-sub-title">البدلاء</h3>${listHtml(subs)}` : ''}
        ${injured.length ? `<h3 class="lu-sub-title">الغيابات</h3><ul class="lu-list">${injured.map(function (x) {
          return `<li><span class="n">✚</span><span>${esc(nameOf(x.player))}</span><span class="meta">${esc([x.type_name, x.injury].filter(Boolean).join(' - '))}</span></li>`;
        }).join('')}</ul>` : ''}
      </section>`;
  }
  function renderLineups(data, info) {
    var html = data ? teamLineupHtml(info.home_team || {}, data, 'home') + teamLineupHtml(info.away_team || {}, data, 'away') : '';
    panels.lineups.innerHTML = html
      ? `<div class="lu-grid">${html}</div>`
      : '<div class="match-message"><span>لم يتم الإعلان عن التشكيلات بعد.</span></div>';
  }

  // ------------------------------------------------------------------ states
  function loader(el, text) {
    el.innerHTML = `<div class="px-loader" role="status"><span class="px-spinner"></span>${text ? `<span>${esc(text)}</span>` : ''}</div>`;
  }
  function message(el, text, retry) {
    el.innerHTML = `<div class="match-message"><span>${esc(text)}</span>${retry ? '<button class="px-retry" type="button">إعادة المحاولة</button>' : ''}</div>`;
    var b = el.querySelector('.px-retry');
    if (b) b.addEventListener('click', function () { fetchMatchDetails(false); });
  }

  // ------------------------------------------------------------------ main
  var matchId = new URLSearchParams(location.search).get('id') || '';
  var refreshTimer = null;
  var busy = false;

  async function fetchMatchDetails(silent) {
    if (busy) return;
    clearTimeout(refreshTimer);
    if (!/^\d{1,12}$/.test(matchId)) {
      message(hero, 'لم يتم تحديد المباراة. اختر مباراة من الصفحة الرئيسية.', false);
      panels.events.innerHTML = ''; panels.lineups.innerHTML = '';
      return;
    }
    if (!silent) { loader(hero, 'جاري تحميل المباراة...'); loader(panels.events); loader(panels.lineups); }
    if (!WORKER_BASE_URL || WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1) {
      console.error('[PX League] Set PXL_WORKER_BASE_URL (top of the theme) to load match details.');
      return;                                                  // keep the spinners
    }
    busy = true;
    try {
      var info;
      try {
        info = await fetchJson(api('match_info', matchId), silent ? 1 : 3);
      } catch (err) {
        console.warn('[PX League] match_info:', err);
        if (!silent) {
          message(hero, String(err && err.message).indexOf('404') !== -1 ? 'المباراة غير موجودة.' : 'تعذّر تحميل بيانات المباراة.', true);
          panels.events.innerHTML = ''; panels.lineups.innerHTML = '';
        }
        return;
      }
      var results = await Promise.allSettled([
        Number(info.events) ? fetchJson(api('matches_event', matchId), silent ? 1 : 2) : Promise.resolve(null),
        Number(info.lineup) ? fetchJson(api('matches_lineup', matchId), silent ? 1 : 2) : Promise.resolve(null)
      ]);
      var ev = results[0].status === 'fulfilled' ? results[0].value : null;
      var lu = results[1].status === 'fulfilled' ? results[1].value : null;

      var st = renderHero(info, ev);
      if (results[0].status === 'rejected') { if (!silent) message(panels.events, 'تعذّر تحميل الأحداث.', true); }
      else renderEvents(ev || {}, info);
      if (results[1].status === 'rejected') { if (!silent) message(panels.lineups, 'تعذّر تحميل التشكيلات.', true); }
      else renderLineups(lu, info);

      if (st === 'live' || (st === 'upcoming' && Number(info.match_timestamp) * 1000 - Date.now() < 30 * 60 * 1000)) {
        refreshTimer = setTimeout(function () { if (!document.hidden) fetchMatchDetails(true); else scheduleOnVisible(); }, REFRESH_MS);
      }
    } finally {
      busy = false;
    }
  }
  function scheduleOnVisible() {
    document.addEventListener('visibilitychange', function once() {
      if (!document.hidden) { document.removeEventListener('visibilitychange', once); fetchMatchDetails(true); }
    });
  }

  // ------------------------------------------------------------------ tabs
  function selectTab(btn, focus) {
    tabs.forEach(function (t) {
      var on = t === btn;
      t.classList.toggle('is-active', on);
      t.setAttribute('aria-selected', on ? 'true' : 'false');
      t.tabIndex = on ? 0 : -1;
      panels[t.getAttribute('data-tab')].hidden = !on;
    });
    if (focus) btn.focus();
    try { history.replaceState(null, '', location.pathname + location.search + '#' + btn.getAttribute('data-tab')); } catch (e) {}
  }
  page.querySelector('.match-tabs').addEventListener('click', function (e) {
    var b = e.target.closest('.match-tab');
    if (b) selectTab(b, false);
  });
  page.querySelector('.match-tabs').addEventListener('keydown', function (e) {
    if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
    var i = tabs.indexOf(document.activeElement);
    if (i === -1) return;
    e.preventDefault();
    selectTab(tabs[(i + (e.key === 'ArrowLeft' ? 1 : -1) + tabs.length) % tabs.length], true);   // RTL
  });
  var initialTab = tabs.filter(function (t) { return '#' + t.getAttribute('data-tab') === location.hash; })[0];
  if (initialTab) selectTab(initialTab, false);

  window.fetchMatchDetails = fetchMatchDetails;
  fetchMatchDetails(false);
})();
//

//
(function () {
  var slot = document.getElementById('px-player-slot');
  var body = document.getElementById('px-post-body');
  if (!slot || !body) return;

  var frame = null;
  var marker = body.querySelector('[data-stream-src]');
  if (marker) {
    var src = marker.getAttribute('data-stream-src') || '';
    if (/^https:\/\//i.test(src)) {
      frame = document.createElement('iframe');
      frame.src = src;
    }
    marker.remove();
  } else {
    frame = body.querySelector('iframe');
  }
  if (!frame) return;   // regular article: the arena stays hidden, the post shows normally

  frame.setAttribute('allow', 'autoplay; fullscreen; encrypted-media; picture-in-picture');
  frame.setAttribute('allowfullscreen', 'true');
  frame.setAttribute('title', document.title);
  frame.removeAttribute('width');
  frame.removeAttribute('height');
  frame.removeAttribute('style');
  slot.textContent = '';
  slot.appendChild(frame);

  // Stream found: show the arena (its title replaces the article title)
  var arena = document.getElementById('px-arena');
  var postTitle = document.getElementById('px-post-title');
  if (arena) arena.hidden = false;
  if (postTitle) postTitle.hidden = true;
})();
//

//
(function () {
  'use strict';

  // ------------------------------------------------------------------ configuration
  var WORKER_BASE_URL = window.PXL_WORKER_BASE_URL || '';    // set once at the top of the file (SETTINGS)
  var MATCH_FILTERS = '[]/[]/["8634"]';
  var TEAM_LOGO_BASE = 'https://imgs.ysscores.com/teams/128/';
  var LEAGUE_LOGO_BASE = 'https://imgs.ysscores.com/championship/64/';
  var MAX_ATTEMPTS = 3;                                       // tries before an error is shown
  var REFRESH_MS = 60 * 1000;                                 // silent refresh (visible tab only)
  var LIVE_WINDOW_MS = 3.5 * 60 * 60 * 1000;

  var container = document.getElementById('matches-api-container');
  if (!container) return;

  // ------------------------------------------------------------------ helpers
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

  function cairoDate(d) {                                     // YYYY-MM-DD in Africa/Cairo
    var p = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo' }).formatToParts(d);
    var get = function (t) { return p.find(function (x) { return x.type === t; }).value; };
    return get('year') + '-' + get('month') + '-' + get('day');
  }
  function cairoTime(unixSeconds) {                           // HH:MM in Africa/Cairo
    var n = Number(unixSeconds);
    if (!n) return '--:--';
    return new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(n * 1000));
  }
  function imageUrl(base, file) {                             // only plain file names like "4151761254960.png"
    var f = file ? String(file).trim() : '';
    return /^[\w.-]+\.(png|jpe?g|webp|gif|svg)$/i.test(f) ? base + encodeURIComponent(f) : '';
  }

  var dateEl = document.getElementById('fixtures-date');
  try {
    dateEl.textContent = new Intl.DateTimeFormat('ar-EG', { timeZone: 'Africa/Cairo', weekday: 'long', day: 'numeric', month: 'long' }).format(new Date());
  } catch (e) { /* old browser: no date label */ }

  async function fetchJson(url, attempts) {
    for (var i = 1; ; i++) {
      var ctrl = new AbortController();
      var timer = setTimeout(function () { ctrl.abort(); }, 9000);
      try {
        var res = await fetch(url, { headers: { Accept: 'application/json' }, cache: 'no-store', signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        var json = await res.json();
        if (json && json.status === false) throw new Error(json.message || 'API status false');
        return json;
      } catch (err) {
        if (i >= attempts) throw err;
        await wait(1000 * i);                                 // 1 s, 2 s between attempts
      } finally {
        clearTimeout(timer);
      }
    }
  }

  function matchesUrl(isoDate) {
    return WORKER_BASE_URL + '/api/matches/matches_date_get/' + isoDate + '/' + encodeURI(MATCH_FILTERS) + '/D/60';
  }
  function matchPageUrl(id) {                                 // dedicated match details page
    return '/p/match.html?id=' + encodeURIComponent(id);
  }
  function matchInfoUrl(id) {
    return WORKER_BASE_URL + '/api/matches/match_info/' + encodeURIComponent(id) + '/D/60';
  }

  // ------------------------------------------------------------------ parsing
  function statusOf(raw) {
    var s = Number(raw.status);
    if (s === 0) return 'upcoming';
    if (s === 4) return 'finished';
    var kickoff = Number(raw.match_timestamp) * 1000;
    var now = Date.now();
    return kickoff && now >= kickoff - 10 * 60 * 1000 && now <= kickoff + LIVE_WINDOW_MS ? 'live' : 'other';
  }

  // ysscores 'minutes' = SECONDS since the current half started (ht_time), verified live:
  // status 1 (first half) with minutes 1151 = 19'. Status 3 is assumed to be the second half.
  // Any other live code gets no minute rather than a wrong one.
  function liveMinute(status, seconds) {
    var secs = Number(seconds);
    if (!(secs > 0)) return '';
    var m = Math.floor(secs / 60) + 1;
    var st = Number(status);
    if (st === 1) return m > 45 ? '45+' + (m - 45) : String(m);
    if (st === 3) { var t = 45 + m; return t > 90 ? '90+' + (t - 90) : String(t); }
    return '';
  }

  // Status badge HTML. Live: "مباشر" + ONLY the minute (never the status code), with the
  // minute isolated as LTR so "61'" / "45+2'" render correctly inside the RTL page.
  function liveBadgeHtml(m) {
    if (m.status === 'live') {
      return 'مباشر' + (m.minute ? ` <span dir="ltr">${esc(m.minute)}'</span>` : '');
    }
    return esc(m.status === 'finished' ? 'انتهت' : m.status === 'other' ? 'غير محدد' : 'لم تبدأ');
  }

  function parseMatch(raw) {
    var cc = Array.isArray(raw.channel_commm) && raw.channel_commm.length ? raw.channel_commm[0] : {};
    var champ = raw.championship || {};
    var home = raw.home_team || {};
    var away = raw.away_team || {};
    return {
      id: raw.match_id,
      league: champ.title || 'مباريات',
      leagueLogo: imageUrl(LEAGUE_LOGO_BASE, champ.image),
      round: raw.round || '',
      timestamp: Number(raw.match_timestamp) || 0,
      time: cairoTime(raw.match_timestamp),
      status: statusOf(raw),
      minute: liveMinute(raw.status, raw.minutes),
      home: { name: home.full_title || home.title || '', logo: imageUrl(TEAM_LOGO_BASE, home.image) },
      away: { name: away.full_title || away.title || '', logo: imageUrl(TEAM_LOGO_BASE, away.image) },
      scoreHome: raw.home_scores != null ? raw.home_scores : 0,
      scoreAway: raw.away_scores != null ? raw.away_scores : 0,
      channel: cc.channel_name || '',
      commentator: cc.commentator_name || ''
    };
  }

  // Group by championship.title (API order of first appearance), sort each group by kickoff
  function groupByLeague(matches) {
    var order = [];
    var groups = {};
    matches.forEach(function (m) {
      if (!groups[m.league]) {
        groups[m.league] = { league: m.league, logo: m.leagueLogo, matches: [] };
        order.push(m.league);
      }
      groups[m.league].matches.push(m);
    });
    return order.map(function (name) {
      groups[name].matches.sort(function (a, b) { return a.timestamp - b.timestamp; });
      return groups[name];
    });
  }

  // ------------------------------------------------------------------ templates (current layout)
  var ICON_MIC = '<svg aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-width="2" viewBox="0 0 24 24"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/><path d="M19 11a7 7 0 0 1-14 0M12 18v4M8 22h8"/></svg>';
  var ICON_TV = '<svg aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="m17 2-5 5-5-5"/></svg>';

  function teamHtml(team) {
    var initials = esc(String(team.name || '').trim().slice(0, 2));
    return `
      <div class="team">
        <span class="team__logo">
          <span class="team__initials">${initials}</span>
          ${team.logo ? `<img src="${esc(team.logo)}" alt="${esc(team.name)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}
        </span>
        <span class="team__name">${esc(team.name)}</span>
      </div>`;
  }

  function cardHtml(m) {
    var badgeHtml = liveBadgeHtml(m);
    var center = m.status === 'live' || m.status === 'finished'
      ? `<span class="match-score"><span>${esc(m.scoreHome)}</span><span class="sep">-</span><span>${esc(m.scoreAway)}</span></span>`
      : `<span class="match-time">${esc(m.time)}</span>`;
    var cardStatus = m.status === 'other' ? 'upcoming' : m.status;

    return `
      <a class="match-card match-card--${cardStatus}" href="${esc(matchPageUrl(m.id))}">
        <div class="match-card__top">
          <span class="match-card__league">${esc(m.league)}</span>
          <span class="match-card__round">${esc(m.round)}</span>
        </div>
        <div class="match-card__body">
          ${teamHtml(m.home)}
          <div class="match-center">
            ${center}
            <span class="badge${m.status === 'live' ? ' badge--live' : ''}">${badgeHtml}</span>
          </div>
          ${teamHtml(m.away)}
        </div>
        <div class="match-card__bottom">
          <span class="match-card__meta">${ICON_MIC}<span>${esc(m.commentator || 'غير متوفر')}</span></span>
          <span class="match-card__meta">${ICON_TV}<span>${esc(m.channel || 'غير متوفر')}</span></span>
        </div>
      </a>`;
  }

  function countLabel(n) {
    if (n === 1) return 'مباراة واحدة';
    if (n === 2) return 'مباراتان';
    if (n >= 3 && n <= 10) return n + ' مباريات';
    return n + ' مباراة';
  }

  function groupHtml(g) {
    return `
      <section class="league-group">
        <h2 class="league-group__title">
          ${g.logo ? `<img class="league-group__logo" src="${esc(g.logo)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}
          <span>${esc(g.league)}</span>
          <span class="league-group__count">${countLabel(g.matches.length)}</span>
        </h2>
        <div class="match-list">
          ${g.matches.map(cardHtml).join('')}
        </div>
      </section>`;
  }

  // ------------------------------------------------------------------ states
  function showLoading() {
    container.setAttribute('aria-busy', 'true');
    container.innerHTML = '<div class="px-loader" role="status"><span class="px-spinner"></span><span>جاري تحميل المباريات...</span></div>';
  }
  function showMessage(text, withRetry) {
    container.setAttribute('aria-busy', 'false');
    container.innerHTML = `<div class="match-message"><span>${esc(text)}</span>${withRetry ? '<button class="px-retry" type="button">إعادة المحاولة</button>' : ''}</div>`;
    var btn = container.querySelector('.px-retry');
    if (btn) btn.addEventListener('click', function () { loadMatches(false); });
  }
  function render(matches) {
    var groups = groupByLeague(matches);
    if (!groups.length) { showMessage('لا توجد مباريات اليوم.', false); return; }
    container.setAttribute('aria-busy', 'false');
    container.innerHTML = groups.map(groupHtml).join('');   // spinner is replaced only here
  }

  // ------------------------------------------------------------------ live matches: minute + channel
  var liveInfo = {};                                          // match_id -> { minute, round, channel, commentator }

  function withLiveInfo(m) {
    var info = liveInfo[m.id];
    if (!info) return m;
    if (info.minute) m.minute = info.minute;
    if (info.round && !m.round) m.round = info.round;
    if (info.channel && !m.channel) m.channel = info.channel;
    if (info.commentator && !m.commentator) m.commentator = info.commentator;
    return m;
  }

  async function loadLiveInfo(matches) {
    var live = matches.filter(function (m) { return m.status === 'live'; }).slice(0, 12);
    await Promise.all(live.map(async function (m) {
      try {
        var json = await fetchJson(matchInfoUrl(m.id), 1);
        var d = (json && json.data) || {};
        var cc = Array.isArray(d.channel_commm) && d.channel_commm.length ? d.channel_commm[0] : {};
        liveInfo[m.id] = {
          minute: liveMinute(d.status, d.minutes),
          round: d.round || '',
          channel: cc.channel_name || '',
          commentator: cc.commentator_name || ''
        };
      } catch (e) { /* card stays without minute */ }
    }));
    return matches.map(withLiveInfo);
  }

  // ------------------------------------------------------------------ load
  var hasData = false;
  var loading = false;

  async function loadMatches(silent) {
    if (loading) return;
    loading = true;
    if (!silent || !hasData) showLoading();
    try {
      if (!WORKER_BASE_URL || WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1) {
        // Not configured yet: keep the spinner, tell the site owner in the console
        console.error('[PX League] Set PXL_WORKER_BASE_URL (top of the theme) to your Cloudflare Worker URL.');
        return;
      }
      var json = await fetchJson(matchesUrl(cairoDate(new Date())), MAX_ATTEMPTS);
      var matches = (Array.isArray(json && json.data) ? json.data : []).map(parseMatch);
      matches = await loadLiveInfo(matches);                  // live minute + channel before showing
      render(matches);
      hasData = true;
    } catch (err) {
      console.warn('[PX League] matches:', err);
      if (!hasData) showMessage('تعذّر تحميل المباريات حاليًا.', true);   // keep last good data on refresh errors
    } finally {
      loading = false;
    }
  }

  loadMatches(false);
  setInterval(function () { if (!document.hidden && hasData) loadMatches(true); }, REFRESH_MS);
  document.addEventListener('visibilitychange', function () { if (!document.hidden && hasData) loadMatches(true); });
})();
//
